import { useState } from 'react';
import { Button } from '../components/Button';
import { Switch } from './Switch';
import './notification-settings.css';

// Stand-in for a real API call.
const fakeSave = () => new Promise((resolve) => setTimeout(resolve, 600));

export function NotificationSettings() {
  const [email, setEmail] = useState(true);
  const [push, setPush] = useState(false);
  const [status, setStatus] = useState('idle'); // idle | saving | saved

  const change = (setter) => (value) => {
    setter(value);
    setStatus('idle');
  };

  const save = async () => {
    setStatus('saving');
    await fakeSave();
    setStatus('saved');
  };

  return (
    <main className="notification-settings">
      <h1 className="notification-settings__title">Notifications</h1>
      <Switch Label="Email notifications" checked={email} onChange={change(setEmail)} />
      <Switch Label="Push notifications" checked={push} onChange={change(setPush)} />
      <Button Label={status === 'saving' ? 'Saving…' : 'Save'} Disabled={status === 'saving'} onClick={save} />
      <p className="notification-settings__status" role="status">
        {status === 'saved' ? 'Your notification settings have been saved.' : ''}
      </p>
    </main>
  );
}

