import { useState } from 'react';
import '../styles/tokens.css';
import './notification-settings.css';
import { Switch } from '../components/Switch.jsx';
import { Button } from '../components/Button.jsx';

export function NotificationSettings() {
  const [email, setEmail] = useState(true);
  const [push, setPush] = useState(false);
  const [saved, setSaved] = useState(false);

  // Any change after saving makes the confirmation stale.
  const update = (setter) => (value) => { setter(value); setSaved(false); };

  return (
    <main className="notification-settings">
      <h1 className="notification-settings__title">Notification settings</h1>
      <Switch Label="Email notifications" checked={email} onChange={update(setEmail)} />
      <Switch Label="Push notifications" checked={push} onChange={update(setPush)} />
      <div className="notification-settings__actions">
        <Button Label="Save" onClick={() => setSaved(true)} />
        <p className="notification-settings__status" role="status">{saved ? 'Settings saved' : ''}</p>
      </div>
    </main>
  );
}

