import { useState } from 'react';
import { Button } from '../components/Button';
import { Chip } from '../components/Chip';
import { Field } from '../components/Field';
import { Tag } from '../components/Tag';
import './search-header.css';

const RANGES = ['Today', 'This week', 'This month'];

export function SearchHeader({ onSearch }) {
  const [query, setQuery] = useState('');
  const [range, setRange] = useState(null);

  function handleSubmit(event) {
    event.preventDefault();
    onSearch?.({ query, range });
  }

  return (
    <form role="search" className="search-header" onSubmit={handleSubmit}>
      <div className="search-header__row">
        <div className="search-header__field">
          <Field label="Search" type="search" placeholder="Search" onChange={(e) => setQuery(e.target.value)} />
        </div>
        <Button Label="Search" type="submit" />
      </div>
      <div className="search-header__filters" role="group" aria-label="Date range">
        {RANGES.map((label, i) => (
          <span key={label} className="search-header__filter">
            <Chip Label={label} pressed={range === label} onClick={() => setRange(range === label ? null : label)} />
            {i === 0 && <Tag Label="New" />}
          </span>
        ))}
      </div>
    </form>
  );
}

