import { useEffect, useRef, useState } from 'react';
import { Button } from '../components/Button.jsx';
import { Field } from '../components/Field.jsx';
import './account-settings.css';

// How long "Changes saved" stays before it goes away by itself.
const CONFIRMATION_MS = 4000;

export function AccountSettings({ displayName = 'Ada', onSave }) {
  const [saved, setSaved] = useState(false);
  const timer = useRef();

  useEffect(() => () => clearTimeout(timer.current), []);

  function handleSubmit(event) {
    event.preventDefault();
    onSave?.({ displayName: new FormData(event.currentTarget).get('displayName') });
    setSaved(true);
    clearTimeout(timer.current);
    timer.current = setTimeout(() => setSaved(false), CONFIRMATION_MS);
  }

  return (
    <main className="account-settings">
      <h1 className="account-settings__heading">Account settings</h1>
      <form className="account-settings__form" onSubmit={handleSubmit}>
        <Field name="displayName" label="Display name" value={displayName} onChange={() => setSaved(false)} />
        <div className="account-settings__actions">
          <Button type="submit" />
          {/* Tidepool has no toast or banner, and Tag is only for statuses that don't change, so this is plain text. */}
          <p className="account-settings__confirmation" role="status">{saved ? 'Changes saved' : ''}</p>
        </div>
      </form>
    </main>
  );
}

